    <script>
      const statusMessage = document.getElementById("status-message");
      const cartCount = document.getElementById("cart-count");
      const bagLink = document.getElementById("bag-link");
      const dismissPromo = document.getElementById("dismiss-promo");
      const promoBanner = document.getElementById("promo-banner");

      let count = 0;

      function announce(message) {
        statusMessage.textContent = "";
        window.setTimeout(() => {
          statusMessage.textContent = message;
        }, 20);
      }

      function updateBagLabel() {
        bagLink.setAttribute("aria-label", `Shopping bag, ${count} item${count === 1 ? "" : "s"}`);
      }

      document.querySelectorAll("[data-add]").forEach((button) => {
        button.addEventListener("click", () => {
          const productName = button.getAttribute("data-product-name");
          count += 1;
          cartCount.textContent = String(count);
          updateBagLabel();
          announce(`${productName} added to bag. Bag now has ${count} item${count === 1 ? "" : "s"}.`);
        });
      });

      document.querySelectorAll("[data-favorite]").forEach((button) => {
        button.addEventListener("click", () => {
          const isPressed = button.getAttribute("aria-pressed") === "true";
          button.setAttribute("aria-pressed", String(!isPressed));
          button.classList.toggle("button--pressed", !isPressed);
          const card = button.closest("article");
          const productName = card ? card.querySelector("h3")?.textContent?.trim() : "item";
          announce(`${productName} ${!isPressed ? "saved" : "removed from saved items"}.`);
        });
      });

      dismissPromo.addEventListener("click", () => {
        promoBanner.hidden = true;
        announce("Promotion dismissed.");
      });

      updateBagLabel();
    </script>
