         color: var(--color-muted-text);
         font-size: 0.95rem;
       }

       .site-footer {
         display: grid;
         gap: 1rem;
         padding: 1.5rem 0 2.25rem;
         border-top: 1px solid var(--color-border);
       }

       .footer-grid {
         display: grid;
         grid-template-columns: 1.2fr 0.8fr;
         gap: 1rem;
       }

       .footer-copy {
         color: var(--color-muted-text);
         max-width: 44rem;
       }

       .site-footer nav ul {
         display: flex;
         flex-wrap: wrap;
         gap: 1rem 1.25rem;
         list-style: none;
         padding: 0;
         margin: 0;
       }

       .status-bar {
         position: fixed;
         right: 1rem;
         bottom: 1rem;
         max-width: min(24rem, calc(100vw - 2rem));
         padding: 0.85rem 1rem;
         border-radius: 1rem;
         border: 1px solid var(--color-border);
         background: var(--color-surface-3);
         color: var(--color-text);
         box-shadow: var(--shadow-1);
       }

       .sr-only {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       .sr-only:not(:focus):not(:active) {
         clip-path: inset(50%);
       }

       @media (prefers-reduced-motion: no-preference) {
         html {
           scroll-behavior: smooth;
         }

         .skip-link,
         .button,
         .utility-nav a,
         .site-nav a,
         .promo__button {
           transition:
             transform 160ms ease,
             background-color 160ms ease,
             border-color 160ms ease,
             color 160ms ease,
             box-shadow 160ms ease;
         }

         .button:hover,
         .utility-nav a:hover,
         .site-nav a:hover {
           transform: translateY(-1px);
         }
       }

       @media (max-width: 900px) {
         .hero,
         .deals-grid,
         .footer-grid {
           grid-template-columns: 1fr;
         }

         .card-grid > li,
         .story-grid > li {
           grid-column: span 12;
         }

         .site-header,
         .section__header,
         .promo__inner {
           flex-direction: column;
           align-items: flex-start;
         }
       }

       @media (max-width: 640px) {
         .site-header {
           padding-top: 0.9rem;
         }

         .brand {
           letter-spacing: 0.05em;
         }

         .site-nav ul,
         .utility-nav ul {
           flex-wrap: wrap;
           gap: 0.7rem 1rem;
         }

         .hero__lead,
         .hero__panel,
         .product-body,
         .deal-card__body,
         .story-card__body {
           padding: 1rem;
         }

         .hero__facts {
           grid-template-columns: 1fr;
         }

         .status-bar {
           left: 1rem;
           right: 1rem;
           max-width: none;
         }
       }

       @media (forced-colors: active) {
         :root {
           --color-bg: Canvas;
           --color-surface: Canvas;
           --color-surface-2: Canvas;
           --color-surface-3: Canvas;
           --color-text: CanvasText;
           --color-muted-text: CanvasText;
           --color-link: LinkText;
           --color-border: ButtonBorder;
           --color-focus: Highlight;
           --color-accent: Highlight;
           --color-accent-2: Highlight;
         }

         body,
         .promo,
         .hero__lead,
         .hero__panel,
         .product-card,
         .deal-card,
         .story-card,
         .status-bar,
         .utility-nav a,
         .button,
         .fact,
         .panel__card {
           background: Canvas;
           color: CanvasText;
           box-shadow: none;
         }

         .brand__mark,
         .panel__visual,
         .product-media,
         .story-media {
           forced-color-adjust: none;
           background: Canvas;
           border: 1px solid ButtonBorder;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <div class="page">
       <aside class="promo" id="promo-banner" aria-label="Store promotion">
         <div class="promo__inner">
           <p class="promo__copy">
             Free shipping on orders over $75, plus next-day delivery on featured edits.
           </p>
           <button
             class="button button--ghost button--compact promo__button"
             type="button"
             id="dismiss-promo"
             aria-label="Dismiss promo: Free shipping on orders over $75"
           >
             Dismiss
           </button>
         </div>
       </aside>

       <header class="site-header">
         <a class="brand" href="#maincontent" aria-label="Aster & Finch home">
           <span class="brand__mark" aria-hidden="true"></span>
           <span>Aster &amp; Finch</span>
         </a>

         <nav class="site-nav" aria-label="Primary">
           <ul>
             <li><a href="#featured-products">Featured</a></li>
             <li><a href="#deals">Deals</a></li>
             <li><a href="#editorial">Editorial</a></li>
           </ul>
         </nav>

         <nav class="utility-nav" aria-label="Store tools">
           <ul>
             <li>
               <a href="#featured-products" id="bag-link" aria-label="Shopping bag, 0 items">
                 Bag <span class="count-badge" id="cart-count" aria-hidden="true">0</span>
               </a>
             </li>
           </ul>
         </nav>
       </header>

       <main id="maincontent" tabindex="-1">
         <section class="section hero" aria-labelledby="home-heading">
           <div class="hero__lead">
             <p class="eyebrow">New season / retail edit</p>
             <h1 id="home-heading">Polished layers, sharp gifts, and everyday upgrades.</h1>
             <p class="hero__summary">
               Discover a streamlined home page for Aster &amp; Finch with standout product picks,
               limited-time offers, and editorial notes to guide the next add-to-cart moment.
             </p>

             <div class="hero__actions">
               <a class="button button--solid" href="#featured-products">Shop featured</a>
               <a class="button button--ghost" href="#deals">Browse deals</a>
             </div>

             <div class="hero__facts" aria-label="Store highlights">
               <p class="fact"><strong>48h</strong>Restocks on key sizes</p>
               <p class="fact"><strong>4.8/5</strong>Average customer rating</p>
               <p class="fact"><strong>12</strong>Curated stories this week</p>
             </div>
           </div>

           <div class="hero__panel" aria-label="Featured look">
             <div class="panel__visual" aria-hidden="true"></div>
             <div class="panel__card">
               <p class="panel__meta">
                 <span class="badge">Editor’s pick</span>
                 <span>Designed for office-to-evening wear</span>
               </p>
               <p class="panel__meta">
                 <span>Layered neutrals</span>
                 <span>New arrivals live now</span>
               </p>
             </div>
           </div>
         </section>

         <section class="section" id="featured-products" aria-labelledby="featured-heading">
           <div class="section__header">
             <div>
               <p class="eyebrow">Featured products</p>
               <h2 id="featured-heading">Customer favorites with strong everyday utility.</h2>
             </div>
             <p>
               Each product card keeps one primary link, with separate actions for save and add to bag.
             </p>
           </div>

           <ul class="card-grid">
             <li>
               <article class="product-card" id="coastline-trench">
                 <div
                   class="product-media"
                   aria-hidden="true"
                   style="--media-from:#25354b; --media-mid:#121a26; --media-to:#1e334d; --media-glow:#f2b36d;"
                 ></div>
                 <div class="product-body">
                   <p class="eyebrow">Outerwear</p>
                   <a class="card-link" href="#coastline-trench-details">
                     <h3>Coastline Trench</h3>
                   </a>
                   <p class="product-meta">
                     Water-resistant shell with a soft lining and a clean shoulder line.
                   </p>
                   <p class="product-price">
                     <strong>$148</strong>
                     <span class="badge">Best seller</span>
                   </p>
                   <div class="card-actions">
                     <button
                       class="button button--ghost button--compact"
                       type="button"
                       data-favorite
                       aria-pressed="false"
                       aria-label="Save Coastline Trench"
                     >
                       Save
                     </button>
                     <button
                       class="button button--solid button--compact"
                       type="button"
                       data-add
                       data-product-name="Coastline Trench"
                       aria-label="Add Coastline Trench to bag"
                     >
                       Add to bag
                     </button>
                   </div>
                   <p class="sr-only" id="coastline-trench-details">
                     Tailored enough for meetings, relaxed enough for a weekend layer.
                   </p>
                 </div>
               </article>
             </li>

             <li>
               <article class="product-card" id="meridian-knit">
                 <div
                   class="product-media"
                   aria-hidden="true"
                   style="--media-from:#2a3046; --media-mid:#151a29; --media-to:#37466c; --media-glow:#77ddb8;"
                 ></div>
                 <div class="product-body">
                   <p class="eyebrow">Knitwear</p>
                   <a class="card-link" href="#meridian-knit-details">
                     <h3>Meridian Knit</h3>
                   </a>
                   <p class="product-meta">
                     Midweight ribbed sweater with a relaxed drape and double-wrapped cuffs.
                   </p>
                   <p class="product-price">
                     <strong>$86</strong>
                     <span class="badge">New</span>
                   </p>
                   <div class="card-actions">
                     <button
                       class="button button--ghost button--compact"
                       type="button"
                       data-favorite
                       aria-pressed="false"
                       aria-label="Save Meridian Knit"
                     >
                       Save
                     </button>
                     <button
                       class="button button--solid button--compact"
                       type="button"
                       data-add
                       data-product-name="Meridian Knit"
                       aria-label="Add Meridian Knit to bag"
                     >
                       Add to bag
                     </button>
                   </div>
                   <p class="sr-only" id="meridian-knit-details">
                     A soft staple that sits neatly under coats, jackets, and blazers.
                   </p>
                 </div>
               </article>
             </li>

             <li>
               <article class="product-card" id="foundry-tote">
                 <div
                   class="product-media"
                   aria-hidden="true"
                   style="--media-from:#3b2d25; --media-mid:#14181f; --media-to:#594237; --media-glow:#f2b36d;"
                 ></div>
                 <div class="product-body">
                   <p class="eyebrow">Accessories</p>
                   <a class="card-link" href="#foundry-tote-details">
                     <h3>Foundry Tote</h3>
                   </a>
                   <p class="product-meta">
                     Structured carryall with room for a laptop, lunch, and the rest of the day.
                   </p>
                   <p class="product-price">
                     <strong>$118</strong>
                     <span class="badge">Work-ready</span>
                   </p>
                   <div class="card-actions">
                     <button
                       class="button button--ghost button--compact"
                       type="button"
                       data-favorite
                       aria-pressed="false"
                       aria-label="Save Foundry Tote"
                     >
                       Save
                     </button>
                     <button
                       class="button button--solid button--compact"
                       type="button"
                       data-add
                       data-product-name="Foundry Tote"
                       aria-label="Add Foundry Tote to bag"
                     >
                       Add to bag
                     </button>
                   </div>
                   <p class="sr-only" id="foundry-tote-details">
                     Durable construction and a sleek silhouette for daily commuting.
                   </p>
                 </div>
               </article>
             </li>
           </ul>
         </section>

         <section class="section" id="deals" aria-labelledby="deals-heading">
           <div class="section__header">
             <div>
               <p class="eyebrow">Deals</p>
               <h2 id="deals-heading">Limited-time offers with straightforward value.</h2>
             </div>
             <p>Clear pricing, visible savings, and no hidden interaction patterns.</p>
           </div>

           <div class="deals-grid">
             <article class="deal-card deal-card--featured">
               <div class="deal-card__body deal-card__hero">
                 <p class="badge">20% off selected outerwear</p>
                 <h3>Refresh the top layer before the temperature drops.</h3>
                 <p class="deal-card__copy">
                   Apply the seasonal discount to trench coats, shell jackets, and insulated vests.
                 </p>
                 <ul class="deal-card__list">
                   <li>Ends Sunday at midnight</li>
                   <li>Free exchanges for 30 days</li>
                   <li>Gift wrap available at checkout</li>
                 </ul>
                 <a class="button button--solid button--compact" href="#featured-products">Shop outerwear</a>
               </div>
             </article>

             <div class="deal-list">
               <article class="deal-card">
                 <div class="deal-card__body">
                   <p class="badge">Bundle &amp; save</p>
                   <h3>Buy any two accessories, save 15% on the pair.</h3>
                   <p class="deal-card__copy">
                     Pair a tote with a belt, wallet, or scarf for an easy checkout win.
                   </p>
                   <a class="button button--ghost button--compact" href="#featured-products">See accessories</a>
                 </div>
               </article>

               <article class="deal-card">
                 <div class="deal-card__body">
                   <p class="badge">Member perk</p>
                   <h3>Early access to editorial drops and restock alerts.</h3>
                   <p class="deal-card__copy">
                     Members get first notice when best sellers return in key sizes.
                   </p>
                   <a class="button button--ghost button--compact" href="#editorial">Read the stories</a>
                 </div>
               </article>
             </div>
           </div>
         </section>

         <section class="section" id="editorial" aria-labelledby="editorial-heading">
           <div class="section__header">
             <div>
               <p class="eyebrow">Editorial</p>
               <h2 id="editorial-heading">Short reads that help shoppers choose with confidence.</h2>
             </div>
             <p>Styled like a magazine spread, structured like a simple content grid.</p>
           </div>

           <ul class="story-grid">
             <li>
               <article class="story-card">
                 <div
                   class="story-media"
                   aria-hidden="true"
                   style="--media-from:#233148; --media-mid:#111824; --media-to:#2f4868; --media-glow:#8eb4ff;"
                 ></div>
                 <div class="story-card__body">
                   <div class="story-card__meta">
                     <span>Style guide</span>
                     <span>5 min read</span>
                   </div>
                   <h3>How to build a three-layer wardrobe with fewer, better pieces.</h3>
                   <p class="story-card__copy">
                     A simple formula for mixing outerwear, knitwear, and carryalls without overbuying.
                   </p>
                   <a class="button button--ghost button--compact" href="#featured-products">Explore looks</a>
                 </div>
               </article>
             </li>

             <li>
               <article class="story-card">
                 <div
                   class="story-media"
                   aria-hidden="true"
                   style="--media-from:#3a2d3d; --media-mid:#151821; --media-to:#514057; --media-glow:#ef8484;"
                 ></div>
                 <div class="story-card__body">
                   <div class="story-card__meta">
                     <span>Behind the edit</span>
                     <span>3 min read</span>
                   </div>
                   <h3>The color story behind the season’s darker neutrals.</h3>
                   <p class="story-card__copy">
                     Warm browns, deep navy, and softened black create contrast without losing calm.
                   </p>
                   <a class="button button--ghost button--compact" href="#deals">See offers</a>
                 </div>
               </article>
             </li>
           </ul>
         </section>
       </main>

       <footer class="site-footer">
         <div class="footer-grid">
           <div>
             <p class="eyebrow">Aster &amp; Finch</p>
             <p class="footer-copy">
               A refined retail storefront built with semantic HTML, accessible interactions, and a
               dark visual style tuned for browsing featured products, deals, and editorial content.
             </p>
           </div>

           <nav aria-label="Footer">
             <ul>
               <li><a href="#featured-products">Featured</a></li>
               <li><a href="#deals">Deals</a></li>
               <li><a href="#editorial">Editorial</a></li>
             </ul>
           </nav>
         </div>
       </footer>
     </div>

     <div class="status-bar sr-only" id="status-message" aria-live="polite" aria-atomic="true"></div>

     <script>
       const statusMessage = document.getElementById("status-message");
       const cartCount = document.getElementById("cart-count");
       const bagLink = document.getElementById("bag-link");
       const dismissPromo = document.getElementById("dismiss-promo");
       const promoBanner = document.getElementById("promo-banner");

       let count = 0;

       function announce(message) {
         statusMessage.textContent = "";
         window.setTimeout(() => {
           statusMessage.textContent = message;
         }, 20);
       }

       function updateBagLabel() {
         bagLink.setAttribute("aria-label", `Shopping bag, ${count} item${count === 1 ? "" : "s"}`);
       }

       document.querySelectorAll("[data-add]").forEach((button) => {
         button.addEventListener("click", () => {
           const productName = button.getAttribute("data-product-name");
           count += 1;
           cartCount.textContent = String(count);
           updateBagLabel();
           announce(`${productName} added to bag. Bag now has ${count} item${count === 1 ? "" : "s"}.`);
         });
       });

       document.querySelectorAll("[data-favorite]").forEach((button) => {
         button.addEventListener("click", () => {
           const isPressed = button.getAttribute("aria-pressed") === "true";
           button.setAttribute("aria-pressed", String(!isPressed));
           button.classList.toggle("button--pressed", !isPressed);
           const card = button.closest("article");
           const productName = card ? card.querySelector("h3")?.textContent?.trim() : "item";
           announce(`${productName} ${!isPressed ? "saved" : "removed from saved items"}.`);
         });
       });

       dismissPromo.addEventListener("click", () => {
         promoBanner.hidden = true;
         announce("Promotion dismissed.");
       });

       updateBagLabel();
     </script>
   </body>
 </html>

')
